test('day 365 saves the annual evidence summary without exposing final materials or declaring exam readiness',async()=>{
  const f=fixture({id:'reflection-365',skill:'reflection',title:'年度总结',week:52,questions:[]},{search:'?day=365',setup:(data,mat,tasks)=>{data.weeks.push({week:52,title:'年度总结',level:'B2'});data.days.push({day:365,week:52,weekday:8,totalMinutes:360,tasks:[{...tasks.at(-1),materialIds:[mat.id],minutes:360}]});}});await Promise.resolve();assert.equal(f.win.IELTSTodayNavigation.current().day,365);await f.nodes.get('courseBegin').fire('click');const input=f.nodes.get('courseOutput').querySelector('textarea');assert.ok(input);assert.match(f.nodes.get('courseOutput').textContent,/训练证据仍需补齐/);input.value='听读说写仍需补齐独立作品和延迟测评，下一周期先补基础与待评证据，继续按真实结果推进。';await input.fire('input');f.advance(1000);const save=f.nodes.get('courseOutput').querySelectorAll('button').find(b=>/保存年度总结/.test(b.textContent));await save.fire('click');assert.equal(f.records().length,1);assert.equal(f.records()[0].source,'year-review');assert.equal(f.records()[0].evaluation.result,'unverified');assert.equal(JSON.parse(f.records()[0].answer).yearSummary.readiness.ready,false);assert.match(f.nodes.get('courseResult').textContent,/年度总结已保存/);const exposures=JSON.parse(f.map.get(f.win.IELTSCoursePlayer.KEY)).exposures;assert.deepEqual(Object.keys(exposures),['reflection-365']);
});

test('a premature B-form start never opens its body or records exposure',async()=>{const f=fixture({pool:'gate',form:'B',assessmentGroup:'gate-04',week:4});await Promise.resolve();await f.nodes.get('courseTasks').children.find(n=>n.dataset.taskId==='reading').fire('click');await f.nodes.get('courseBegin').fire('click');assert.equal(f.nodes.get('courseSession').hidden,true);assert.match(f.nodes.get('courseNotice').textContent,/B卷继续保留/);assert.equal(f.map.has(f.win.IELTSCoursePlayer.KEY),false);assert.equal(f.records().length,0);});

test('planned first practice and repeated IDs are labelled separately from the learner exposure record',async()=>{const coverage=require('../assets/curriculum-coverage.js'),f=fixture({}, {window:{IELTSCurriculumCoverage:coverage},setup:(data,mat,tasks)=>{for(const task of tasks)task.materialPractice=[{materialId:mat.id,cycle:'scheduled-reuse',firstPlannedDay:1}];}});await Promise.resolve();await f.nodes.get('courseTasks').children.find(n=>n.dataset.taskId==='reading').fire('click');assert.match(f.nodes.get('courseMaterials').textContent,/计划巩固同ID/);assert.match(f.nodes.get('courseMaterialIntro').textContent,/个人实际曝光另核对/);await f.nodes.get('courseBegin').fire('click');assert.match(f.nodes.get('courseExposure').textContent,/开始时未见/);});

test('media-only unsubmitted activity can exhaust the homepage budget and cannot open another course attempt',async()=>{const P=require('../assets/year-planner.js'),media=[{id:'work-writing-pending',kind:'writing',mode:'writing_path',dayNumber:1,transcript:{format:'ielts-writing-path-v1',plan:{id:'p'},steps:{self:{draft:'keep my words',activity:{id:'draft-activity',startedAt:'2026-10-24T06:00:00.000Z',endedAt:'2026-10-24T12:00:00.000Z',activeSeconds:21600,activityByDate:{'2026-10-24':21600}}}}}}],before=JSON.stringify(media),f=fixture({}, {window:{IELTSYearPlanner:P,IELTSMediaLibrary:{list:async()=>structuredClone(media)}}});await new Promise(resolve=>setImmediate(resolve));await f.nodes.get('courseTasks').children.find(n=>n.dataset.taskId==='reading').fire('click');await f.nodes.get('courseBegin').fire('click');assert.match(f.nodes.get('courseNotice').textContent,/360分钟学习预算已用完/);assert.equal(f.win.IELTSTodayNavigation.budget().spentMinutes,360);assert.equal(f.win.IELTSTodayNavigation.current().active,false);assert.equal(f.records().length,0);assert.equal(JSON.stringify(media),before);f.advance(86400000);await f.nodes.get('courseBegin').fire('click');assert.equal(f.win.IELTSTodayNavigation.current().active,true);assert.equal(JSON.stringify(media),before);});

test('newly observed media activity pauses an already active course and keeps the exact unfinished answers',async()=>{const P=require('../assets/year-planner.js'),media=[{id:'work-dialogue-live',kind:'speaking_text',mode:'dialogue',dayNumber:1,transcript:{format:'ielts-dialogue-v1',state:{taskId:'intro'},activity:{id:'talk-live',startedAt:'2026-10-24T06:00:00.000Z',endedAt:'2026-10-24T12:00:00.000Z',activeSeconds:21590,activityByDate:{'2026-10-24':21590}}}}],f=fixture({}, {window:{IELTSYearPlanner:P,IELTSMediaLibrary:{list:async()=>structuredClone(media)}}});await new Promise(resolve=>setImmediate(resolve));await f.nodes.get('courseTasks').children.find(n=>n.dataset.taskId==='reading').fire('click');await f.nodes.get('courseBegin').fire('click');const input=f.nodes.get('courseQuestions').querySelectorAll('input').find(n=>n.value==='red');input.checked=true;await input.fire('change');f.advance(1000);await new Promise(resolve=>setImmediate(resolve));media[0].transcript.activity.activeSeconds=21600;media[0].transcript.activity.activityByDate['2026-10-24']=21600;f.advance(1000);await new Promise(resolve=>setImmediate(resolve));assert.match(f.nodes.get('courseNotice').textContent,/360分钟预算已用完/);assert.equal(f.records().length,0);const draft=Object.values(JSON.parse(f.map.get(f.win.IELTSCoursePlayer.KEY)).drafts)[0];assert.equal(draft.answers.q1,'red');assert.equal(draft.submittedAt,undefined);assert.equal(f.nodes.get('courseSubmit').disabled,true);});
